        textarea2.setValue("$c.date test\n" + dateTest);
        textarea3.setValue("$c.str test\n" + strTest);
    }).catch(function(err){
        console.error(err);
    });
}
// async await の例
scwin.trigger_page1_onclick = async function() {
    try {
        var jsonArr = [{
            "src": "/path/common/util.xml",
            "name": "$c.util",
            "reload": "true" // $c.utilが既に読み込まれている場合、再度読み込みます。
        },{
            "src": "/path/common/data.xml",
            "name": "$c.data",
            "reload": "false" // $c.dataが既に読み込まれている場合、読み込まずに既存の$c.dataを維持します。（デフォルト値はfalse）
        },{
            "src": "/path/common/date.xml",
            "name": "$c.date"
        },{
            "src": "/path/common/str.xml",
            "name": "$c.str"
        }];
        await $p.loadGlobalCommon(jsonArr);        var dataTest = $c.data.getMatchedJSON(dataList1, [
            { columnId : "col1", operator : "==", value : "0"},
            { columnId : "col2", operator : "==", value : "1", logical : "||" }
        ]);
        var dateTest = $c.date.addHour("2024042511", 10);
        var strTest = $c.str.lpad("24", 4, "0");
        textarea1.setValue("$c.data test\n" + JSON.stringify(dataTest, undefined, 4));
        textarea2.setValue("$c.date test\n" + dateTest);
        textarea3.setValue("$c.str test\n" + strTest);
    } catch(err) {
        console.error(err);
    }
}
