// 戻り値の例) Sun Jan 01 2012 00:00:00 GMT+0900 (JST)

// 例3)var objDate3 = $p.parseDate("2012-01-01", "yyyyMMdd");
// 戻り値の例) Sun Jan 01 2012 00:00:00 GMT+0900 (JST)

// 例4)
var objDate4 = $p.parseDate("01222013112430", "MMddyyyyHHmmss");
