getRuntimeId.!doc:
実行時点のコンポーネントIDを返す

WFrameのScope機能を使用すると、各画面のコンポーネントIDは実行時点で固有IDに変更されます

WFrameに構成されたコンポーネントのID生成規則は「WFrameのID」+「_」+「コンポーネントID」の形式です

**Parameters:**

```id``` - ```String:Y``` - 画面に定義したコンポーネントID

**Return:**

```String``` - 実行時点のコンポーネントID

**Since:**

5.0_3.3377A.20181128.161740

**Sample:**

```javascript
// 次の例は「Websquare Configure」のclient.config.xml編集モードで「Overview」タブの「strictMode -> scope variable」の値が「mf」と定義されている場合です（この設定はデフォルト値です）
// 画面構成は次のとおりです
// 'main.xml'と'sub.xml'にInputコンポーネントが構成されており、それぞれのIDは同じく'ibx_exam1'と定義されています
// 'main.xml'にはWFrameコンポーネントが構成されており、プロパティ'src'の値は'sub.xml'に指定されています

// (main.xml UI構成例)
// <w2:input id='ibx_exam1'/>
// <w2:wframe id='wfm_exam1' src='sub.xml'/>

// (sub.xml UI構成例)
// <w2:input id='ibx_exam1'/>

// (main.xmlスクリプト例)
var strId = $p.getRuntimeId("ibx_exam1");
// 戻り値の例) 'mf_ibx_exam1'

// (sub.xmlスクリプト例)
var strId = $p.getRuntimeId("ibx_exam1");
// 戻り値の例) 'mf_wfm_exam1_ibx_exam1'

executeWorkflow.!doc:
定義されたワークフローをIDで実行するか、ワークフローオブジェクトを直接定義して実行します

**Parameters:**

```workflow``` - ```String|Object:Y``` - ワークフローのIDまたはワークフローオブジェクト

**Since:**

5.0_3.3377A.20181128.161740

**Sample:**

```javascript
//例1) 定義されたワークフローのIDが'wf_exam1'の場合
$p.executeWorkflow("wf_exam1");

//例2) ワークフローオブジェクトを引数として使用する場合

//ワークフローオブジェクトのプロパティは以下の通りです
//workflowObj.id : <String:Y> ワークフローのID
//workflowObj.processMsg : <String:N> ワークフローの通信中に表示するメッセージ (文字列'$blank'を指定するとメッセージウィンドウが表示されません)//workflowObj.resolveCallback : <String||function:N> すべての段階が正常に処理された後に実行する関数を指定
//workflowObj.rejectCallback : <String||function:N> 段階の進行中にレスポンス値エラーまたはエラー発生時に実行する関数を指定
//workflowObj.step : <String:Y> 実行段階が含まれる配列
//workflowObj.step[i].type : <String:Y> [submit, submitDone, 関数] 実行段階のタイプ
//- submit : サブミッション実行。'step.action'にサブミッションのIDを指定 ('step.pre'を指定可能)
//- submitDone : サブミッションレスポンス後に実行され、サブミッションに登録されたイベントハンドラsubmitDoneまたはsubmitErrorが実行される ('step.action'にサブミッションのIDを指定、'step.post'を指定可能)
//- function : function実行。'step.action'に関数名または関数オブジェクトを指定//workflowObj.step[i].action: <String:Y> 実行対象 ('stpe.type'の値に応じて指定できる種類が区別される)
//- 'stpe.type'の値が'submit'または'submitDone'の場合、サブミッションのIDを指定
//- 'stpe.type'の値が'function'の場合、関数名または関数オブジェクトを指定
//workflowObj.step[i].pre : <String||function:N> 'stpe.type'の値が'submit'の時に指定でき、サブミッション実行前に呼び出す関数名または関数オブジェクトを指定 (関数の戻り値がtrueでない場合、サブミッションは実行されない (全体rejectの際はworkflowObj.reject(msg)を呼び出す))
//workflowObj.step[i].post : <String/function:N> 'stpe.type'の値が'submitDone'の時に指定できる (サブミッションの'submit-done'イベントの後に実行される)

let workflowObj = {};workflowObj.id = "wf_exam2";
workflowObj.processMsg = "workflowを実行中です。";

workflowObj.step = [
    { "type": "submit", "action": "sbm_exam1", "pre": "scwin.sbm_exam1_wf_pre" },
    { "type": "function", "action": "scwin.wf_function1" },
    { "type": "submit", "action": "sbm_exam2" },
    { "type": "submitDone", "action": "sbm_exam1", "post": "scwin.sbm_exam1_wf_post" },
    { "type": "submitDone", "action": "sbm_exam2"},
    { "type": "submit", "action": "sbm_exam3" },
    { "type": "function", "action": "scwin.wf_function2" },
    { "type": "submitDone", "action": "sbm_exam3" }
];

workflowObj.resolveCallback = function (wObj) {
    //関数を直接定義
    console.log("# workflow resolveCallback");
    console.log(wObj);
};

workflowObj.rejectCallback = scwin.comm_wf_rejectCallback; //定義された関数を指定
$p.executeWorkflow(workflowObj);

//step.preに指定した関数の戻り値がtrueで、応答がすべて正常な場合の実行順序は次のとおりです
//1. scwin.sbm_exam1_wf_pre
//2. sbm_exam1_submit
//3. sbm_exam1実行
//4. scwin.wf_function1
//5. sbm_exam2_submit
//6. sbm_exam2実行
//7. sbm_exam1_submitdone
//8. scwin.sbm_exam1_wf_post
//9. sbm_exam2_submitdone
//10. sbm_exam3_submit
//11. sbm_exam3実行
//12. scwin.wf_function2
//13. sbm_exam3_submitdone
//14. workflow resolveCallback 

//stpeのpre関数定義例
scwin.sbm_exam1_wf_pre = function (submissionId, workflowObj) {
    //console.log("# scwin.sbm_exam1_wf_pre");
    //console.log(submissionId);
    //console.log(workflowObj);
    //workflowをreject（中断）したい場合は、次のように呼び出します
    //workflowObj.reject();    return true;    //trueを返さないとサブミッションの実行が中断されます
};

//stepのpost関数定義例
scwin.sbm_exam1_wf_post = function (submissionObj, workflowObj) {
    //console.log("# scwin.sbm_exam1_wf_post");
    //console.log(submissionObj);
    //console.log(workflowObj);
    //workflowをreject（中断）したい場合は次のように呼び出します
    //workflowObj.reject();
};
```

