**Sample:**

```javascript
// 以下のように項目を追加せず、chooseOptionプロパティとallOptionプロパティをtrueに定義した場合
<xf:checkcombobox id="checkcombobox1" chooseOption="true" allOption="true" style="position: relative;width: 148px;height: 21px;" 
appearance="minimal" direction="auto"></xf:checkcombobox>

// indexを指定せずに項目を追加checkcombobox1.addItem( "1" , "りんご");
//結果 - "すべて選択"項目の下位（最後）に追加される。項目の順序は"すべて選択"、"りんご"となる。
//      "選択"（chooseOption）は選択可能な項目には含まれず、項目が選択されていない場合にlabelに表示される。

// indexを0に指定して項目を追加
checkcombobox1.addItem( "2" , "オレンジ",0);
//結果 - 0番目に項目が追加され、"すべて選択"項目の上に追加される。項目の順序は"オレンジ"、"すべて選択"、"りんご"となる。
//      "選択"（chooseOption）は選択可能な項目には含まれず、項目が選択されていない場合にlabelに表示される。
```

setRef.!doc:
refプロパティを設定します。DataCollectionと連携させる場合は、必ず「data:」というプレフィックスを付ける必要があります。

指定しない場合、InstanceDataのXPathとして認識されます。

**Parameters:**

```ref``` - ```String:Y``` - refのパス

**Since:**

2.0_1.3134B.20130625.183609

**Sample:**

```javascript
// dataMap1のhobby keyとcheckcombobox1コンポーネントのvalueをバインディングする場合
checkcombobox1.setRef("data:dataMap1.hobby");

// InstanceDataの"res/userData/hobby"と連携する場合
checkcombobox1.setRef("res/userData/hobby");
```

setStyle.!doc:
ウェブスクエアコンポーネントのCSSプロパティを設定します。(ウェブスクエアコンポーネント共通)

**Parameters:**

```property``` - ```String:Y``` - 設定するCSSプロパティ

```value``` - ```String:Y``` - 該当CSSプロパティに適用する値

**Since:**

2.0_1.2639A.20121231.165520

**Sample:**

```javascript
// (例1) コンポーネントのwidthを200pxに設定
componentId.setStyle("width", "200px");

// (例2) 背景色をoliveに変更
componentId.setStyle("background-color","olive");
```

getOriginalID.!doc:
ウェブスクエアコンポーネントのoriginalIDを返します。（ウェブスクエアコンポーネント共通）

originalIDはScope機能を使用する場合に存在します。

scope=trueのWFrameを使用する場合、WFrame内部のコンポーネントIDは、元々ユーザーが定義した値（originalID）の前にprefix（wframeID + _）が追加される方式で変更されます。

この時、originalIDはprefixが追加される前のIDを意味します。

**Return:**

```String``` - コンポーネントのoriginalID

**Since:**

5.0_2.3346B.20181109.170706

**Sample:**

```javascript
// WFrameを使用する多重画面構造の例

// WFrameを含むメイン画面 (main.xml) 
<w2:wframe id="wframe1" src="text.xml" scope="true"/> 

// メイン画面WFrameにロードされるソース画面 (text.xml)<w2:textbox id="textbox1"/>

// text.xmlの画面の内部スクリプトでIDおよびoriginalIDを確認する例。
// getIDの実行 
textbox1.getID(); // 実行結果は "wframe1_textbox1"

// getOriginalIDの実行 
textbox1.getOriginalID(); // 実行結果は "textbox1"
```

checkAll.!doc:
すべての項目を選択または解除します。

**Parameters:**

```checked``` - ```Bollean:Y``` - 選択/解除状態

**Since:**

2.0_1.2639A.20121231.165520

**Sample:**

```javascript
//全選択
checkcombobox1.checkAll(true);

//全解除
checkcombobox1.checkAll(false);
```

trigger.!doc:
コンポーネントで特定のイベントを発生させます。（ウェブスクエアコンポーネント共通）

**Parameters:**

```type``` - ```String:Y``` - 発生させるイベント

```array``` - ```Array:N``` - イベントハンドラーに渡すパラメータ配列

**Since:**

2.0_1.4441B.20141010.114554

**Sample:**

```javascript
// (例1)
// input1コンポーネントにonclickイベントを発生させます。
input1.trigger("onclick");

// (例2)
// input1にonviewchangeイベントを発生させ、ハンドラー関数に(1,2)引数を渡して呼び出します。
input1.trigger("onviewchange", [1,2]);
```

getValue.!doc:
選択された項目のvalueを返します。選択された項目が複数ある場合、delimiterを使用して返されます。

delimiterを設定しない場合、空白（スペース）が区切り文字として使用されます。

**Parameters:**

```delimeter``` - ```String:N``` - 項目区切り文字

**Return:**

```String``` - 選択された項目のvalueが含まれる文字列

**Since:**

2.0_1.2639A.20121231.165520

**Sample:**

```javascript
// valueが"1"と"2"の項目が選択された場合

// 基本APIを使用して取得する場合
var returnValue = checkcombobox1.getValue();
// (戻り値) "1 2"

// ","区切り文字を使用して取得する場合
var returnValue = checkcombobox1.getValue(",");
// (戻り値) "1,2"
```

getPosition.!doc:
ウェブスクエアコンポーネントの位置（left、top）を返します。（ウェブスクエアコンポーネント共通）

位置の値が％で設定されている場合、ピクセルに変換された値を返します。

**Parameters:**

```position``` - ```String:Y``` - [left, top] 位置の種類

**Return:**

```Number``` - コンポーネントの位置の値

**Since:**

2.0_1.2639A.20121231.165520

**Sample:**

```javascript
// 以下のようにinputコンポーネントにCSSプロパティmarginが適用されている場合、
<xf:input id="input1" style="position: relative;width: 144px;height: 21px;margin:10px;"></xf:input>

// （例）上記のinputBoxコンポーネントのtop値を確認
var returnValue = input1.getPosition("top"); 

// ピクセル単位の位置の値が返されます。

// （戻り値）10

getPluginName.!doc:
ウェブスクエアコンポーネントの名前（pluginName）を返します。（ウェブスクエアコンポーネント共通）

**Return:**

```String``` - ウェブスクエアコンポーネントの名前（pluginName）

**Since:**

2.0_1.2639A.20121231.165520

**Sample:**

```javascript
// 以下のように共通関数で動的にウェブスクエアオブジェクトを受け取る場合、コンポーネントの種類に応じた分岐処理が可能です。
var commObj = {};

commObj.fn_makeReqData = function(tmpObj){
    var tmpID = tmpObj.getID(); // コンポーネントID
    var tmpCompType = tmpObj.getPluginName();   // コンポーネント名

    if(tmpCompType == "input"){
        //..業務ロジック..
    }else if(tmpCompType == "gridView"){
        //..業務ロジック..
    }else{
        //..業務ロジック..
```    }
};
```

getUserData.!doc:
setUserDataでウェブスクエアコンポーネントに設定したkeyのvalue、またはユーザーが直接ページソース（XML）にプロパティとして定義したvalueを返します。（ウェブスクエアコンポーネント共通）

**Parameters:**

```key``` - ```String:Y``` - データのkey

**Return:**

```String``` - keyに対応するvalue

**Since:**

2.0_1.2639A.20121231.165520

**Sample:**

```javascript
// Inputコンポーネントにユーザープロパティ（setTest）を設定する例
<xf:input id="input1" style="position: relative;width: 144px;height: 21px;" setTest="Hello"></xf:input>

// 上記で設定したsetTestの値を返す例
input1.getUserData("setTest");
// （戻り値） "Hello"

//setUserDataを通じて'valueTest'（key）と'WebSquare'（data）を設定する例
input1.setUserData("valueTest","WebSquare");
// 上記で設定したsetTestの値を返す例。
input1.getUserData("WebSquare");
// (戻り値) "WebSquare"
```

closeOthers.!doc:
現在アクティブになっているウィンドウ以外のウィンドウを閉じます。

**Parameters:**

```windowId``` - ```String:N``` - 基準となるウィンドウのwindowIdまたはid。引数がない場合は、現在アクティブなウィンドウを基準とします。

**Since:**

5.0_2.3229A.20180727.150112

**Sample:**

```javascript
//アクティブなウィンドウ以外のウィンドウを閉じます。
windowContainer1.closeOthers();


//windowIdに該当するウィンドウを基準に閉じる場合
//createWindow呼び出し時にwindowIDを設定しない場合、titleがwindowIdになります。
windowContainer1.createWindow( "tmp001" , null , "/uiTestW5/test001.xml");

windowContainer1.closeOthers("tmp001");


//windowIdがtitleと異なる設定の場合
windowContainer1.createWindow( "tmp001" , "wc1" , "/uiTestW5/test001.xml");

windowContainer1.closeOthers("wc1");

```

getOpacity.!doc:
ウェブスクエアコンポーネントの不透明度を返します。（ウェブスクエアコンポーネント共通）

エンジン内部的にCSSのopacityプロパティ値を返します。

**Return:**

```Integer``` - Opacity値

**Since:**

2.0_1.1984A.20120424.105444

**Sample:**

```javascript
// inputBoxコンポーネントにopacity CSSを適用
<xf:input id="input1" style="position: relative;width: 144px;height: 21px;opacity:0.2;"></xf:input>

// inputBoxコンポーネントのopacity値を返す
var returnValue = input1.getOpacity(); 
// returnValueは0～1の間の実数
// （戻り値）"0.2"
```

bind.!doc:
コンポーネントにイベントとハンドラー関数を動的に割り当てます。（ウェブスクエアコンポーネント共通）

**Parameters:**

```eventType``` - ```String:Y``` - 割り当てるイベント

```func``` - ```Function:Y``` - イベントに対するハンドラー関数

**Since:**

2.0_1.4441B.20141010.114554

**Sample:**

```javascript
// (例1)
// input1のonclickイベントに対するハンドラー関数を直接定義して割り当てます。
input1.bind("onclick", function(e){ alert(input1.getValue();}));

// (例2)
// あらかじめcommObj.ev_click関数を定義します。
var commObj = {};
commObj.ev_click = function(e){
    alert("click :: "+this.id);
};

// input1コンポーネントにonclickイベントと定義したハンドラー関数を動的に割り当てます。
input1.bind("onclick", commObj.ev_click );

getID.!doc:
ウェブスクエアコンポーネントのIDを返します。(ウェブスクエアコンポーネント共通)

**Return:**

```String``` - ウェブスクエアコンポーネントID

**Since:**

2.0_1.1984A.20120424.105444

**Sample:**

```javascript
// 動的にウェブスクエアコンポーネントが渡された場合、以下のようにIDを確認できます。
function fn_validCheck(tmpObj){
    var compID = tmpObj.getID();
}
// 上記の例でtmpObjが"input1"というIDを持っている場合、
// (戻り値) "input1"
```

getWindowByWindowId.!doc:
引数として渡されたwindowIDを持つウィンドウのウィンドウオブジェクトを返します。

**Parameters:**

```windowId``` - ```String:Y``` - ウィンドウID

```focus``` - ```Boolean:N``` - ウィンドウにフォーカスを与えるかどうか

**Return:**

```Object``` - ウィンドウオブジェクト

**Since:**

2.0_1.2884A.20130401.104932

**Sample:**

```javascript
//createWindow呼び出し時にwindowIDを設定しなかった場合にウィンドウのinput1コンポーネントのvalueを取得する例（titleがIDになる）

//以下のようにwindowIDを設定せずにウィンドウを生成する
windowContainer1.createWindow( "tmp001" , null , "/uiTestW5/test001.xml");

//"tmp001"のIDを持つウィンドウを取得する（titleのIDで設定されている）
var tmpObj = windowContainer1.getWindowByWindowId("tmp001");

//ウィンドウページ内のinput1コンポーネントのvalueを取得する
var tmpRs = tmpObj.input1.getValue();
```

unbind.!doc:
コンポーネントからイベントを削除します。（ウェブスクエアコンポーネント共通）

**Parameters:**

```type``` - ```String:N``` - 削除するイベント（省略した場合、該当コンポーネントのすべてのイベントを削除します）

```func``` - ```Function:N``` - 削除するイベントのハンドラー関数（省略した場合、上記で指定したイベントに登録されているすべてのハンドラー関数を削除します）

**Since:**

2.0_1.4441B.20141010.114554

**Sample:**

```javascript
// （例1）
// input1に登録されているすべてのイベントを削除します。
input1.unbind();

// （例2）
// input1のonviewchangeイベントに対するすべてのハンドラー関数を削除します。
input1.unbind("onviewchange");

// （例3）
// input1のonviewchangeイベントに対するfunc1イベントハンドラー関数を削除します。
```input1.unbind("onviewchange", func1);
```

getUdcHome.!doc:
UDCオブジェクトが自身を定義したUDCファイルのパスをファイル名を含めて返します。（ウェブスクエアコンポーネント共通）

ファイル名は最後の.xmlまで含みます。.xmlを除いたパスはgetUdcRootを使用して返します。

UDCオブジェクトではないコンポーネントから呼び出された場合はundefinedが返されます。

**Return:**

```String``` - UDCファイルパス（UDCでない場合、undefinedが返されます）

**Since:**

5.0_2.3229A.20180727.150112

**Sample:**

```javascript
// 例
// UDCファイルパスは /a/b/udc.xml 
// 画面XMLは  /a/c/main.xml 
// UDCオブジェクトのIDは udc1

udc1.getUdcHome(); 
// (実行結果) /a/b/udc.xml
```

getScope.!doc:
scope=trueのWFrameの子コンポーネントの場合、親WFrameオブジェクトを返します。（ウェブスクエアコンポーネント共通）

scope=trueのWFrameの子コンポーネントでない場合、nullを返します。

**Return:**

```Object``` - WFrameオブジェクトまたはnull

**Since:**

5.0_2.3229A.20180727.150112

**Sample:**

```javascript
// （例）
// メインページにwframe1があり、wframe1内部にwframe11が存在。
// そして、wframe11内部にtextbox1が存在。

textbox1.getScope(); 
// （戻り値） wframe11オブジェクト
```

setUserData.!doc:
ウェブスクエアコンポーネントにユーザーデータを設定します。（ウェブスクエアコンポーネント共通）

コンポーネントに設定可能なkeyを入力する必要があります。設定可能でないkeyの場合、該当内容がログに出力されます。

**Parameters:**

```key``` - ```String:Y``` - 設定するデータのkey

```value``` - ```String:Y``` - 設定するデータのvalue

**Since:**

2.0_1.1984A.20120424.105444

**Sample:**

```javascript
// コンポーネントに'data'というkeyで'WebSquare'というvalueを設定する例。

componentId.setUserData("data", "WebSquare");

// コンポーネントに設定不可能なkeyを入力した場合、key設定が不可能。

componentId.setUserData("title", "WebSquare");
// 以下のようにログが出力されます。
// !!!WARNING - [title] can't be defined as UserData.
```

getWindowByUniqueId.!doc:
渡されたuniqueIDを持つウィンドウのwindowオブジェクトを返します。

**Parameters:**

```uuid``` - ```String:Y``` - ユニークID

```focus``` - ```Boolean:N``` - ウィンドウにフォーカスを与えるかどうか

**Return:**

```Object``` - windowオブジェクト

**Since:**

5.0_2.3229A.20180727.150112

**Sample:**

```javascript
//createWindow呼び出し時にwindowIDを設定しない場合にwindowのinput1コンポーネントのvalueを取得する例（titleがIDとなる）

//以下のようにwindowIDを設定せずにウィンドウを生成する
windowContainer1.createWindow( "tmp001" , null , "/uiTestW5/test001.xml");

// titleが"tmp001"のウィンドウを取得する
var uniqueId = windowContainer1.getUniqueIdByTitle('tmp001');
var tmpObj = windowContainer1.getWindowByWindowId(uniqueId[0]);
```

getUdcRoot.!doc:
UDCオブジェクトが自身を定義したUDCファイルのパスを返します。（ウェブスクエアコンポーネント共通）

ファイル名は含まれません。ファイル名を含むパスを取得するにはgetUdcHomeを使用してください。

UDCオブジェクトではないコンポーネントから呼び出された場合はundefinedが返されます。

**Return:**

```String``` - UDCファイルのパス（UDCでない場合はundefinedが返されます）

**Since:**

5.0_2.3229A.20180727.150112

**Sample:**

```javascript
// 例
// UDCファイルのパス：/a/b/udc.xml 
// 画面XMLのパス：/a/c/main.xml 
// UDCオブジェクトのID：udc1

udc1.getUdcRoot();    
// （実行結果）/a/b/
```

getWindow.!doc:
引数として渡されたtitleを持つウィンドウのwindowオブジェクトを返します。

ウィンドウにリンクされたウェブスクエアページの関数やコンポーネントなどにアクセスする際に使用されます。

**Parameters:**

```title``` - ```String:Y``` - ウィンドウのタイトル

**Return:**

```Object``` - windowオブジェクト

**Since:**

2.0_1.1984A.20120424.105444

**Sample:**

```javascript
//"edu001"というタイトルを持つウィンドウにあるinput1コンポーネントにアクセスして値を取得する場合

//"edu001"というタイトルを持つウィンドウを取得
var tmpObj = windowContainer1.getWindow("edu001");

//ウィンドウページ内のinput1コンポーネントの値を取得
var tmpRs = tmpObj.input1.getValue();
```

getSelectedWindowId.!doc:
選択されたウィンドウのwindowIdを返します。

createWindow APIを呼び出す際にwindowIdを設定しない場合、titleの値がIDとして設定されます。

**Since:**

2.0_1.3260B.20130812.175556

**Sample:**

```javascript
//CASE 1. 以下のようにwindowIDを設定せずにウィンドウを作成した場合
windowContainer1.createWindow( "page001" , null , "/uiTestW5/test0001.xml");

var tmpRs1 = windowContainer1.getSelectedWindowId();
//戻り値の例 ) "page001"

//CASE 2. 以下のようにwindowIDを設定してウィンドウを作成した場合
windowContainer1.createWindow( "page001" , null , "/uiTestW5/test0001.xml", "page001" , "p001");

var tmpRs2 = windowContainer1.getSelectedWindowId();
//戻り値の例 ) "p001"
```

setEventPause.!doc:
指定したイベントを中断します。（ウェブスクエアコンポーネント共通）

**Parameters:**

```eventList``` - ```String:N``` - 中断するイベントのリスト。（nullを指定した場合、該当コンポーネントのすべてのユーザーイベントが中断または中断解除されます。）

```pause``` - ```Boolean:Y``` - イベント中断の有無。

|property|type|description|
|:-|:-|:-|
|true|中断|null|
|false|中断解除|null|

**Since:**

5.0_1.1437A.20141127.170713

**Sample:**

```javascript
// （例1）
// onclickイベントを中断。
input1.setEventPause("onclick", true);

// （例2）
// onfocusおよびonblurイベントの中断を解除。
input1.setEventPause("onfocus,onblur", false);
```

// (例3)
// input1に登録されたすべてのユーザーイベントを中断。
input1.setEventPause(null, true);
```

createWindow.!doc:
ウィンドウを生成（オープン）します。

**Parameters:**

```title``` - ```String:Y``` - ツールバーのネームレイヤーに表示されるタイトル。

```iconUrl``` - ```String:Y``` - 現在は使用されておらず、nullを入力します。カスタムアイコンはuserIconClassで代替されます。

```src``` - ```String:Y``` - ウィンドウにリンクするページのURL。

```windowTitle``` - ```String:N``` - ウィンドウのヘッダーに表示されるタイトル。nullまたは""を入力するとtitleの値が出力されます。

```windowId``` - ```String:N``` - ウィンドウID。nullまたは""を入力するとtitleがIDとして生成されます。

```openAction``` - ```String:N``` - [existWindow, newWindow, selectWindow]existWindow：同じIDのウィンドウが開いている場合、そのウィンドウを使用して再表示します / newWindow：常に新しいウィンドウを生成します / selectWindow：同じIDのウィンドウがある場合、そのウィンドウを選択します
```closeAction``` - ```String:N``` - ウィンドウが閉じられる時の動作を指定する関数名（戻り値はbooleanでなければならない。falseの場合は閉じる動作を中止、trueの場合は閉じる）

```windowTooltip``` - ```String:N``` - ツールバーのネームレイヤーに表示されるツールチップ（未入力の場合、windowTitleがツールチップとして設定される）

```windowHeaderHTML``` - ```String:N``` - ウィンドウ上部のヘッダー中央領域に表示する内容。DOM要素の入力が可能

```options``` - ```Object:N``` - ウィンドウ生成時に設定する追加オプション

|property|type|description|
|:-|:-|:-|
|options.fixed|<Boolean>|固定ピンの有効化の可否|
|options.useNameLayer|<Boolean>|ネームレイヤーの表示の可否|
|options.defaultWidth|<String>|ウィンドウのデフォルト幅|
|options.defaultHeight|<String>|ウィンドウのデフォルト高さ|

```frameMode``` - ```String:N``` - ウィンドウの種類を設定します。frameMode = "iframe" の場合、iframeウィンドウを生成します。frameMode = "wframe" の場合、wframeウィンドウを生成します。frameMode = "pageFrame" (AI新機能) の場合、pageFrameウィンドウを生成します。

```userIconClass``` - ```String:N``` - 各ウィンドウのアイコンのimage srcが含まれているユーザー定義class名です。

```userIconPosition``` - ```String:N``` - ユーザー定義アイコンを固定ピンの左側に配置するか右側に配置するかを設定します。"left"、"right"、デフォルトは"right"です。

```msaName``` - ```String:N``` - msa機能を使用する場合、適用するmsaサーバーの名前を指定します。この値はconfig.xmlに設定されたmsaServerリストに存在する値である必要があります。

**Since:**

2.0_1.1984A.20120424.105444

**Sample:**

```javascript

//CASE1 別途オプションなしでウィンドウを生成する場合windowContainer1.createWindow( "edu001" , null , "/uiTestW5/searchBox.xml" );
//IDがedu001のウィンドウが生成され、ヘッダーのタイトルおよび下部ツールバーのネームレイヤーに"edu001"の値が適用されます。

//CASE2 closeActionおよび詳細オプションを適用してウィンドウを生成する場合

//scriptブロックに以下のようにウィンドウのclose制御functionを定義します。 - createWindow APIを呼び出す際にcloseActionで使用します。
function fn_closeMsg(){
     return confirm("do you close this window?"); // 確認、キャンセルボタンがあるメッセージウィンドウを使用します。
     //return false; // 無条件で閉じるのをキャンセルします。
}

windowContainer1.createWindow( "music" , "" , "/test/music.xml", "page001", "P0001", "existWindow", "fn_closeMsg");
//IDがP0001のウィンドウが生成され、下部ツールバーのネームレイヤーには"music"、ヘッダーのタイトルには"page001"の値が適用されます。// この window が閉じられる時に fn_closeMsg Function が呼び出されます。

// 新しく開かれるウィンドウにパラメータを渡すことができます（dataObject を使用）//

// 実際に渡すデータを定義
 var rowJSON = { 
        "Personal Info" : { "Name": "Lee", "Age": 50, "Married" : false}, 
        "Region": "Seoul", 
        "Carrier": true
        };


// ウィンドウオプションと渡すデータを定義します（dataObject を通じて渡すことができます）           
var obj = {
        "title" : "Test", 
        "windowID": "001", 
        "frameMode" : "wframe", 
        "src" : "popup_sub.xml",
        "userIconClass" : "w2windowContainer_nameLayer_imageIcon1",
        "userIconPosition" : "left",
        "dataObject": {
            "type" : "json", 
            "name" : "windowParam", 
            "data" : rowJSON
            }
        };

// ウィンドウを生成します。                  windowCon1.createWindow(obj);


// 新しく開いたウィンドウから受け取ったデータを確認する例

// var paramData = $p.getParameter("windowParam");
//  var data = JSON.stringify(paramData);
// alert(data);



```

