// getOriginalIDの実行 
textbox1.getOriginalID(); // 実行結果は "textbox1"
```

getChild.!doc:
コンポーネントのIDと、そのコンポーネントが属する繰り返し部分のインデックスに基づいてコンポーネントオブジェクトを返します。

**Parameters:**

```index``` - ```Number:Y``` - 返されるコンポーネントが属する繰り返し部分のインデックス（表示順）

```id``` - ```String:Y``` - 返されるコンポーネントの初期設定ID

**Return:**

```Object``` - 繰り返し部分で見つかったウェブスクエアコンポーネント

**Since:**

2.0_1.1984A.20120424.105444

**Sample:**

```javascript
// 以下のようにGeneratorを定義（InputとTriggerを含むGroupが繰り返し部分に属する）
<w2:generator id="generator1" style="position: relative;">
    <xf:group id="group1" style="position: relative;padding:10px;" class="">
        <xf:input id="input1"            style="position: relative;width: 144px;height: 21px;margin-right:10px;">
        </xf:input>
        <xf:trigger type="button" id="trigger1"
            style="position: relative;width: 80px;height: 23px;">
            <xf:label><![CDATA[getValue]]></xf:label>
        </xf:trigger>
    </xf:group>
</w2:generator>


// 4つの配列データに基づいて繰り返し部分を生成し、
// inputコンポーネントのvalueを変更する例

var tmpArr = ["田中","イ・グァンス","イ・ソンヒ","リュ・スンリョン"]; //配列データ

// 上部で定義された配列の数だけ繰り返し部分を追加
for(var i=0;i < tmpArr.length;i++){
    // 繰り返し部分を追加
    generator1.insertChild(i);
    // 追加された繰り返し部分からinput1コンポーネントオブジェクトを取得
    var tmpChild = generator1.getChild( i , "input1" );
    // inputのvalueを配列データのi番目の値に設定    tmpChild.setValue(tmpArr[i]);
}

```

