**Sample:**

```javascript
var a = WebSquare.bigDecimal("111111111111111");
var b = WebSquare.bigDecimal("222222222222222");
var c = WebSquare.bigDecimal("0");
var result = a.divide(b);
console.log(result.toString());
var result2 = a.divide(c); //0で除算する場合、NaNを表すbigDecimalデータを返します。
console.log(result2.toString());
```

calc.!doc:
expression(演算式)を入力として受け取り、bigDecimal演算を実行します。(a+b*cのような形式)

expressionで使用されるoperand(被演算子)は、bigDecimal型またはbigDecimalに変換可能な型である必要があります。

SP4以降では、$p.bigDecimal.calc();の形式で呼び出す必要があります。WebSquare.bigDecimal.calcで呼び出すと、正しく動作しない可能性があります。

**Parameters:**

```expression``` - ```String:Y``` - 演算式

**Return:**

```Object``` - 演算結果をbigDecimalで返します。

**Since:**

2.0_1.4077B.20140514.225705

**Sample:**

```javascript
// (例1)
var a = $p.bigDecimal("123456789012345678901234567890"); 
var b = $p.bigDecimal("111111111111111111111111111111");
var c = $p.bigDecimal("678901234567890123456789012345");var d = $p.bigDecimal("345678934567893456789345678934");
var ret = $p.bigDecimal.calc("a + b c + (d - a) / (c + d)"); 
input1.setValue(ret); 
//演算結果がinput1に正しく表示されます。

// (例2)
var a = $p.bigDecimal("1234");
var b = 3000;
var ret = $p.bigDecimal.calc ("a+b*b-b/(a+b)"); 
// Number + bigDecimalの演算も可能です。ただし、Numberは17桁以下である必要があります。

// (例3)
var a = "abcd"; // NaN
var b = $p.bigDecimal("200");
var ret = $p.bigDecimal.calc("a + b");
input2.setValue(ret); 
// 演算結果はNaNデータを表すbigDecimalタイプです。数値タイプではないデータと演算すると、すべてNaNが返されます。
```

ajax.!doc:
ajax通信用関数

**Parameters:**

```options``` - ```Object:Y``` - JSON形式オブジェクト

|property|type|description|
|:-|:-|:-|
|options.action|ajaxリクエスト先アドレス|null|
|options.mode|asynchronous(デフォルト)/synchronous|null|
|options.mediatype|application/x-www-form-urlencoded·application/json·application/xml·text/xml|null|
|options.method|get/post/put/delete|null|
|options.requestData|リクエスト本文|null|
|options.requestHeader|リクエストヘッダーに任意で追加する内容（必要な場合のみ使用）|null|
|options.timeout|ajaxリクエスト後のタイムアウト時間。この時間内に応答がない場合、errorコールバック関数を実行|null|
|options.beforeAjax|リクエスト前に実行される関数。この関数内でfalseを返すとajaxリクエストを行わない|null|
|options.success|リクエストが成功した場合に実行されるコールバック関数|null|
|options.error|リクエストが失敗した場合に実行されるコールバック関数|null|
|options.externalHandler|暗号化·復号化連携のような外部データ連携時にデータ変換を担当するユーザー関数。引数としてoptionオブジェクトを渡し、option.requestDataでデータにアクセスできる。ユーザー関数はデータ変換後、Stringを返す必要がある。|null|

**Since:**

2.0_1.1984A.20120424.105444

**Sample:**

```javascript
//上記の例のoptions.successに指定したコールバック関数の定義形式。
doSucess = function(e) {
//eはウェブスクエアエンジンで通信後の結果を格納するJSONオブジェクトである。
//e.resourceUri - 通信URIを返す
//e.responseHeaders - Response Headersの内容を返す
//e.responseStatusCode - Response Status Codeを返す
//e.responseReasonPhrase - Response Status Textを返す
//e.responseBody - Response DataをXMLデータにparseしたXMLオブジェクトを返す。(Response Content-TypeがJSONの場合、jsonオブジェクトをXMLにパース)
//e.responseText - Response Data原本をString形式で返す    
//responseTextをalertで出力。
alert("success\n" + e.responseText);
};

doError = function(e) { //functionを直接定義した場合。
//e.errorType - "target-error" 固定値を返す
//e.resourceUri - 通信URIを返す
//e.responseHeaders - Response Headersの内容を返す
//e.responseStatusCode - Response Status Codeを返す
//e.responseReasonPhrase - Response Status Textを返す
//e.requestBody - Request DataをString形式で返す
//e.responseText - Response Data原本をString形式で返す

//status codeをalertで出力。
alert("errorCode:" + e.responseStatusCode);
};  

var options = {};
options.action = "../$p/extra/test.jsp";
options.mode = "asynchronous";
options.mediatype = "text/xml";
options.method = "post";
options.requestData = "<test/>";
options.requestHeader = {"temp1":"hello", "temp2":"world"}; // temp1およびtemp2ヘッダーをリクエストヘッダーに追加options.success = doSucess;
options.error = doError;
WebSquare.net.ajax( options );
```
